=== clients.ts ===
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// The shape the server returns and the query key everything that shows clients shares. Two features
// stay in step by invalidating ['clients']; nothing imports a sibling to refresh it.
export type Client = { id: number; name: string; email: string };

export const clientsKey = ['clients'] as const;

export function useClients() {
  return useQuery({
    queryKey: clientsKey,
    queryFn: () => getJson<Client[]>('/api/clients'),
  });
}

export function useCreateClient() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { name: string; email: string }) =>
      postJson<Client>('/api/clients', input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: clientsKey }),
  });
}
=== ClientProjects.tsx ===
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

// The projects a client is doing work on, shown in the client's detail. Server data is read straight
// from the SHARED ['projects'] query key (CLAUDE.md rule 5) — the same key the Projects page uses —
// so creating a project anywhere refreshes this list too, with no import of the projects feature.
// Each project carries its clientId, so the client context is just a filter on that shared data.
type Project = { id: number; name: string; clientId: number; clientName: string };

export function ClientProjects({ clientId }: { clientId: number }) {
  const { data: projects } = useQuery({
    queryKey: ['projects'] as const,
    queryFn: () => getJson<Project[]>('/api/projects'),
  });

  if (!projects) {
    return null;
  }

  const owned = projects.filter((project) => project.clientId === clientId);

  if (owned.length === 0) {
    return <p data-testid="client-projects-empty">No projects for this client yet.</p>;
  }

  // Reuse the project-row-<id>/project-name anchors inside the client-context table.
  return (
    <table data-testid="client-projects-table">
      <thead>
        <tr>
          <th>Name</th>
        </tr>
      </thead>
      <tbody>
        {owned.map((project) => (
          <tr key={project.id} data-testid={`project-row-${project.id}`}>
            <td data-testid="project-name">{project.name}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
=== ClientForm.tsx ===
import { useState } from 'react';
import { isValidEmail } from './email';
import { useCreateClient } from './clients';

// Add-a-client form. useState holds only what the user is currently typing; on submit it validates
// the email, and only a proper address POSTs and invalidates the ['clients'] key. A blank or
// malformed email surfaces client-form-email-error and never creates a row.
export function ClientForm() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [emailError, setEmailError] = useState(false);
  const create = useCreateClient();

  return (
    <form
      data-testid="client-form"
      onSubmit={(event) => {
        event.preventDefault();
        if (!isValidEmail(email)) {
          setEmailError(true);
          return;
        }
        setEmailError(false);
        create.mutate(
          { name, email },
          {
            onSuccess: () => {
              setName('');
              setEmail('');
            },
          },
        );
      }}
    >
      <input
        data-testid="client-form-name"
        placeholder="Name"
        value={name}
        onChange={(event) => setName(event.target.value)}
      />
      <input
        data-testid="client-form-email"
        placeholder="Email"
        value={email}
        onChange={(event) => {
          setEmail(event.target.value);
          if (emailError) {
            setEmailError(false);
          }
        }}
      />
      {emailError && (
        <span data-testid="client-form-email-error" role="alert">
          Enter a valid email address.
        </span>
      )}
      <button data-testid="client-form-submit" type="submit">
        Add client
      </button>
    </form>
  );
}

